-- Roguelike parity with Standard: add custom spells 200100 and 350001-350010 (Mythic+ advancement auras) and their script names.
-- Idempotent (delete+insert). Data-only; the spell_mp_* scripts are not compiled into either binary.
DELETE FROM `spell_dbc` WHERE `ID` = 200100 OR `ID` BETWEEN 350001 AND 350010;
DELETE FROM `spell_script_names` WHERE `spell_id` BETWEEN 350001 AND 350010;
